import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with (ROOT / name).open() as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def as_float(value, default=0.0):
    if value is None:
        return default
    text = str(value).strip()
    if text == '':
        return default
    return float(text)


def as_int(value):
    return int(float(str(value).strip()))


def aliases_for(panel):
    aliases = panel.get('alias_labels', [])
    if aliases is None:
        aliases = []
    elif isinstance(aliases, str):
        aliases = [part.strip() for part in aliases.split(',') if part.strip()]
    return [panel.get('panel_name', ''), *aliases]


def flatten_review_panels(manifest):
    panels = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') == 'review':
                panels.append(panel)
    return panels


def latest_contract_for(panel, contract_rows):
    refs = set(aliases_for(panel))
    matches = [
        row for row in contract_rows
        if row.get('status_flag') == 'current' and row.get('panel_ref') in refs
    ]
    if not matches:
        raise ValueError(f"No current contract found for {panel.get('panel_code')}")
    return max(matches, key=lambda row: row.get('effective_week', ''))


def active_labs_by_panel(override_rows):
    best = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        rev_text = (row.get('rev') or '').strip()
        labs_text = (row.get('active_labs') or '').strip()
        if not rev_text or not labs_text:
            continue
        panel_code = row.get('panel_code')
        rev = int(float(rev_text))
        labs = as_int(labs_text)
        current = best.get(panel_code)
        if current is None or rev > current['rev']:
            best[panel_code] = {'rev': rev, 'active_labs': labs}
    return {panel_code: value['active_labs'] for panel_code, value in best.items()}


def money(value):
    return round(float(value) + 0.0, 2)


def cadence_metrics(total_payment, active_labs, reagent_cost_per_1000, tests_per_lab_per_run, shipper_cost, runs_per_year):
    annual_revenue = total_payment * active_labs * runs_per_year
    annual_reagent_cost = reagent_cost_per_1000 * active_labs * tests_per_lab_per_run * runs_per_year / 1000.0
    annual_shipper_cost = shipper_cost * runs_per_year
    annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
    return {
        'annual_revenue_usd': money(annual_revenue),
        'annual_reagent_cost_usd': money(annual_reagent_cost),
        'annual_shipper_cost_usd': money(annual_shipper_cost),
        'annual_margin_usd': money(annual_margin),
    }


def main():
    manifest = load_json('panel_manifest.json')
    holdouts = load_json('holdouts.json')
    template = load_json('report_template.json')
    shipper_rows = load_csv('shipper_cost.csv')
    contract_rows = load_csv('contract_terms.csv')
    network_rows = load_csv('network_adjustments.csv')
    override_rows = load_csv('lab_capacity_overrides.csv')

    excluded = {
        row.get('panel_code')
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }
    shipper_costs = {row['shipper_class']: as_float(row['shipper_cost_usd']) for row in shipper_rows}
    network_adjustments = {
        row['network_tier']: as_float(row['network_adjustment_per_run_per_lab_usd'])
        for row in network_rows
    }
    active_labs_overrides = active_labs_by_panel(override_rows)

    panels = []
    for panel in flatten_review_panels(manifest):
        panel_code = panel['panel_code']
        if panel_code in excluded:
            continue

        contract = latest_contract_for(panel, contract_rows)
        base_payment = as_float(contract['base_payment_per_run_per_lab_usd'])
        network_adjustment = network_adjustments.get(panel.get('network_tier'), 0.0)
        total_payment = base_payment + network_adjustment
        active_labs = active_labs_overrides.get(panel_code, as_int(panel['default_active_labs']))
        shipper_cost = shipper_costs[panel['shipper_class']]
        reagent_cost = as_float(panel['reagent_cost_per_1000_tests_usd'])

        m14 = cadence_metrics(
            total_payment=total_payment,
            active_labs=active_labs,
            reagent_cost_per_1000=reagent_cost,
            tests_per_lab_per_run=as_float(panel['tests_per_lab_per_run_14_day']),
            shipper_cost=shipper_cost,
            runs_per_year=26,
        )
        m28 = cadence_metrics(
            total_payment=total_payment,
            active_labs=active_labs,
            reagent_cost_per_1000=reagent_cost,
            tests_per_lab_per_run=as_float(panel['tests_per_lab_per_run_28_day']),
            shipper_cost=shipper_cost,
            runs_per_year=13,
        )

        panels.append({
            'panel_code': panel_code,
            'panel_name': panel['panel_name'],
            'active_labs': active_labs,
            'base_payment_per_run_per_lab_usd': money(base_payment),
            'network_adjustment_per_run_per_lab_usd': money(network_adjustment),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'shipper_cost_usd': money(shipper_cost),
            'annual_revenue_14_day_usd': m14['annual_revenue_usd'],
            'annual_reagent_cost_14_day_usd': m14['annual_reagent_cost_usd'],
            'annual_shipper_cost_14_day_usd': m14['annual_shipper_cost_usd'],
            'annual_margin_14_day_usd': m14['annual_margin_usd'],
            'annual_revenue_28_day_usd': m28['annual_revenue_usd'],
            'annual_reagent_cost_28_day_usd': m28['annual_reagent_cost_usd'],
            'annual_shipper_cost_28_day_usd': m28['annual_shipper_cost_usd'],
            'annual_margin_28_day_usd': m28['annual_margin_usd'],
            'annual_margin_difference_28_minus_14_usd': money(m28['annual_margin_usd'] - m14['annual_margin_usd']),
        })

    panels.sort(key=lambda row: row['panel_code'])

    total_14 = money(sum(row['annual_margin_14_day_usd'] for row in panels))
    total_28 = money(sum(row['annual_margin_28_day_usd'] for row in panels))
    total_difference = money(total_28 - total_14)
    absolute_difference = money(abs(total_difference))
    threshold = 6000.0
    decision = 'adopt_28_day' if absolute_difference < threshold else 'keep_14_day'

    report = {
        'metadata': template['metadata'],
        'audit_notes': template['audit_notes'],
        'analysis': {
            'assumptions': {
                'runs_per_year_14_day': 26,
                'runs_per_year_28_day': 13,
                'shipper_cost_usd_basis': 'per shipment; annual shipper cost equals shipper_cost_usd multiplied by runs_per_year',
                'decision_threshold_usd': money(threshold),
                'currency': 'USD',
            },
            'panels': panels,
            'totals': {
                'total_annual_margin_14_day_usd': total_14,
                'total_annual_margin_28_day_usd': total_28,
                'total_margin_difference_28_minus_14_usd': total_difference,
                'absolute_total_margin_difference_usd': absolute_difference,
            },
            'recommendation': {
                'decision': decision,
                'justification': (
                    f"Absolute total margin difference is ${absolute_difference:,.2f}, "
                    f"with a decision threshold of ${threshold:,.2f}; therefore {decision}."
                ),
            },
        },
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w') as f:
        json.dump(report, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# Diagnostic Panel Cadence Policy Summary',
        f"Total 14-day margin (USD): ${total_14:,.2f}",
        f"Total 28-day margin (USD): ${total_28:,.2f}",
        f"Absolute difference (USD): ${absolute_difference:,.2f}",
        f"Decision: {decision}",
        f"Justification: absolute difference ${absolute_difference:,.2f} compared with threshold ${threshold:,.2f}.",
    ]
    (ROOT / 'diagpanel_policy_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

